// The last thirty friendship stories (owner's call, 2026-11-27: every character wants something, changes, and pays
// off what you did for them). Before these, half the regulars had only their conversation lines. Same rules as
// friends.js: part n opens at friendship n, one part per visit, five parts to finish; choices set flags that later
// parts read ({ if } / { unless }); the last part is the payoff, something you keep. Plain talk, the way people talk.
// Each story grows out of the thing that regular already told you about themselves (heart.js).
export const ARCS3 = {
  // ---------------- Central District ----------------
  walt: { title: 'Route 9, All Stops', parts: [
    [['walt', 'They\'re cutting Route 9. The transit board says not enough riders. Budget.'], ['walt', 'Not enough riders. I drive forty people a day to the pharmacy and the clinic. Who do they think those are?'],
      ['choice', [{ t: 'Ask him who rides Route 9', reply: [['walt', 'Mrs. Ochoa. Mr. Pham and his oxygen. Two kids who\'d have to walk across Harbor Boulevard to school. People who don\'t have a car or a choice.']] }, { t: 'Ask when the board decides', reply: [['walt', 'Two weeks. Public comment at the end. Three minutes a person.']] }]]],
    [['narr', 'You ride Route 9 on your lunch break. Walt knows every rider by name and every pothole by feel.'], ['walt', 'The board counts tickets. Tickets don\'t tell you anything. Half these folks ride on a free pass.'],
      ['choice', [{ t: 'Help him collect the riders\' stories in writing', set: 'route9Stories', reply: [['walt', 'Letters. Yeah. Mrs. Ochoa is going to write ten pages. She does not know how to write a short letter.']] }, { t: 'Help him count the riders by hand for a week', set: 'route9Count', reply: [['walt', 'A clicker and a clipboard. Okay. Real numbers. I like that.']] }]]],
    [['walt', 'I have to stand up there and talk. Me. I drive a bus. I don\'t talk to boards.'], ['walt', 'In the flood, I knew the route better than the water. This, I don\'t know.'],
      ['choice', [{ t: 'Tell him to talk about the riders, not the budget', set: 'route9Talk', reply: [['walt', 'Talk about Mrs. Ochoa. Okay. I can talk about Mrs. Ochoa for an hour.']] }, { t: 'Suggest he let a rider speak for the route', reply: [['walt', 'Mrs. Ochoa already signed up. She bought a new hat for it.']] }]]],
    [['narr', 'The board meeting runs late. Walt stands at the microphone in his uniform shirt, holding a stack of letters.', { if: 'route9Stories' }], ['narr', 'The board meeting runs late. Walt stands at the microphone with a clipboard: 1,184 rides in one week.', { if: 'route9Count' }],
      ['walt', 'These are my riders. They don\'t have three minutes to come down here. So I brought them.'], ['narr', 'The board votes. Route 9 stays. Mrs. Ochoa stands up and claps by herself for a long time, and then everyone does.']],
    [['walt', 'They gave me the old destination sign when they replaced the bus. I want you to have it.'], ['narr', 'It\'s a long roll of cloth: ROUTE 9 · ALL STOPS.'], ['walt', 'What matters to people isn\'t always what you\'d think. You took this seriously anyway. Thank you.']]
  ] },
  tasha: { title: 'Nobody Goes Alone', parts: [
    [['tasha', 'I keep thinking about that man. Four in the morning, nobody came. You remember I told you?'], ['tasha', 'The hospital has a program for it, other places do. Volunteers who sit with people at the end, so nobody goes alone. We don\'t have one here.'],
      ['choice', [{ t: 'Tell her she should start one', reply: [['tasha', 'Me? I\'m retired. ...I know. That\'s exactly why it should be me.']] }, { t: 'Ask what it would take', reply: [['tasha', 'Volunteers, training, and a charge nurse who doesn\'t think I\'m a nosy old lady. Two out of three is hard.']] }]]],
    [['tasha', 'The hospital said yes. Now I need people. Eight volunteers, minimum. Nights.'],
      ['choice', [{ t: 'Suggest she ask Lt. Okonkwo', set: 'tashaOkonkwo', reply: [['tasha', 'The flowers man. He\'ll say yes and apologize for something. Fine.']] }, { t: 'Offer to put a sign-up sheet at HQ', set: 'tashaFlyer', reply: [['tasha', 'Cops on night shift who can sit still and be quiet. I\'ll take every one I can get.']] }]]],
    [['tasha', 'First training night is Thursday. I have six people. One of them is nineteen and terrified.'], ['tasha', 'And I\'m sixty-eight. What if I can\'t do it anymore? What if I just sit there?'],
      ['choice', [{ t: 'Tell her sitting there is the whole job', reply: [['tasha', '...Sitting there is the whole job. Yeah. I taught that to nurses for thirty years. Thanks for teaching it back to me.']] }, { t: 'Tell her the nineteen-year-old will learn it from her', reply: [['tasha', 'She will. I\'ll make sure. That\'s how I learned it.']] }]]],
    [['narr', 'Four in the morning, a radio call: a hospice patient at the urgent care, no family coming. Tasha\'s first volunteer goes.'], ['tasha', 'She held his hand for two hours. She said he squeezed back once. That\'s all. That\'s everything.']],
    [['tasha', 'We have fourteen volunteers now.'], ['tasha', 'Lt. Okonkwo takes Tuesday nights. He sat with a woman for three hours last week and apologized to her for being late.', { if: 'tashaOkonkwo' }], ['tasha', 'Three of them are officers from your sign-up sheet. They\'re good at it. Quiet. Steady.', { if: 'tashaFlyer' }],
      ['narr', 'She pins a small silver pin to your uniform shirt. It says: NO ONE ALONE.'], ['tasha', 'If you ever get the chance, sit with them. You know that already. Now you have the pin.']]
  ] },
  leon: { title: 'Nineteen Years of Hallways', parts: [
    [['leon', 'My wife says the drawings have to go. Two thousand. I can\'t throw out a single one.'], ['leon', 'But what if I gave them back? To the kids. Most of them are grown now.'],
      ['choice', [{ t: 'Suggest a show at the Central Library', set: 'leonLibrary', reply: [['leon', 'A show. Like a museum. For crayon drawings. ...You know, Mrs. Okafor would love that.']] }, { t: 'Offer to help him find the grown-up kids', reply: [['leon', 'I know every name. I just don\'t know where any of them went.']] }]]],
    [['leon', 'I wrote the name on the back of every one. Every one. Even the ones that were just a scribble.'], ['narr', 'He hands you a drawing: a stick-figure police officer with arms down to the ground. On the back: "Danny R., grade 2, 2011."'],
      ['choice', [{ t: 'Offer to look up old classes in the school records with him', reply: [['leon', 'The office lets me in at night. I have the keys to everything. Don\'t tell anybody.']] }, { t: 'Suggest he post a note at Founders Plaza', reply: [['leon', 'A note at the plaza. Everybody walks through there eventually.']] }]]],
    [['leon', 'We\'re hanging them Saturday. I\'m nervous. It\'s just crayons. What if nobody comes?'], ['leon', 'What if they come and they don\'t remember me?'],
      ['choice', [{ t: 'Tell him they will remember the man who knew their names', reply: [['leon', 'Good morning, Leon. That\'s all it took for me. ...Okay. Okay. Saturday.']] }, { t: 'Promise to come yourself', set: 'leonCome', reply: [['leon', 'In uniform? The little ones still think you\'re a superhero. The arms are long, though.']] }]]],
    [['narr', 'Saturday. The library\'s back room is wall-to-wall crayon. Grown men in work boots are finding their own names and going quiet.', { if: 'leonLibrary' }], ['narr', 'Saturday. The school gym is wall-to-wall crayon. Grown men in work boots are finding their own names and going quiet.', { unless: 'leonLibrary' }],
      ['narr', 'A woman in scrubs stops at a drawing of a sun with a face. She reads the back and starts crying.'], ['leon', 'Keisha. Grade one. Good morning, Keisha.']],
    [['leon', 'Danny came. Danny R., the long arms. He\'s a firefighter now. He said he drew a cop because one walked him home once.'], ['leon', 'I kept one back for you. One of the kids drew it last week.'],
      ['narr', 'It\'s a stick figure in a dark blue uniform with very long arms, standing next to a man with a mop. The back says: "Officer and Mr. Leon. They know my name."']]
  ] },
  carmen: { title: 'The Kitchen in Utuado', parts: [
    [['carmen', 'Come, taste. Something is missing. I make this every day and today something is missing.'], ['carmen', 'It\'s the kitchen. I can\'t remember the color of my kitchen. The tiles. Green? Yellow? I don\'t know anymore.'],
      ['choice', [{ t: 'Sit with her and ask what else she remembers', set: 'carmenSat', reply: [['carmen', 'The window over the sink. The mango tree. My mother singing off-key. The tiles... I don\'t know.']] }, { t: 'Ask if anyone else from Utuado lives nearby', reply: [['carmen', 'In this city? Maybe. There was a woman on the Eastside, they say. Bea something.']] }]]],
    [['carmen', 'My grandchildren don\'t know how to cook any of it. They eat it. They don\'t know it.'], ['carmen', 'I want to write it down. All of it. But I don\'t write recipes. I cook with my hands.'],
      ['choice', [{ t: 'Offer to write while she cooks', set: 'carmenBook', reply: [['carmen', 'You write, I cook. If you write "a little," I will hit you with the spoon. Write how much.']] }, { t: 'Suggest her grandkids cook with her on Sundays', set: 'carmenSundays', reply: [['carmen', 'They will complain. Then they will eat. Then they will learn. That\'s how I learned.']] }]]],
    [['narr', 'Tía Bea from the Eastside is at Carmen\'s table. Two old women from the same mountain are arguing about a sofrito.'], ['bea', 'Your kitchen? Yellow. Everybody in that valley had the yellow tile from the store in town. Yellow with a little blue flower.'], ['carmen', 'Yellow. With a blue flower. ...Yes. Yes.']],
    [['carmen', 'I found someone who paints tiles. One tile. Yellow, with a little blue flower.'], ['carmen', 'It\'s going over my stove. I\'ll see it every time I cook. Then I won\'t forget.'],
      ['choice', [{ t: 'Help her hang it', reply: [['narr', 'It takes the two of you twenty minutes and a lot of arguing about level. It\'s perfect.']] }, { t: 'Tell her the kitchen is still there as long as she cooks it', reply: [['carmen', 'You listen to old ladies. Good. Most people don\'t.']] }]]],
    [['carmen', 'Sit. This one is for you.'], ['narr', 'A plate, and a small stapled booklet: LA COCINA DE CARMEN. Every amount is written out. Nothing says "a little."', { if: 'carmenBook' }], ['narr', 'A plate. Her grandson cooked it. He watches you take the first bite like it\'s an exam.', { if: 'carmenSundays' }],
      ['carmen', 'Yellow tiles. A mango tree. My mother singing. Now you know my kitchen too. That makes it a little less gone.']]
  ] },
  priya: { title: 'Level Five', parts: [
    [['priya', 'My father\'s seventieth birthday is in two weeks. I want to make his mother\'s dal. The one from Pune.'], ['priya', 'I\'ve tried eleven times. It\'s close. It\'s not right. He\'d know in one bite.'],
      ['choice', [{ t: 'Ask what she thinks is missing', reply: [['priya', 'Something sour. Not lemon. Something older than lemon.']] }, { t: 'Offer to be her taste tester', set: 'anjaliTaste', reply: [['priya', 'You eat a level three. You\'re not qualified. ...Okay, fine. You\'re hired.']] }]]],
    [['priya', 'Kokum. It\'s a dried fruit. Nobody in Port Meridian sells it. I\'ve called everywhere.'],
      ['choice', [{ t: 'Suggest asking Rosa at the Eastside bodega', set: 'anjaliRosa', reply: [['priya', 'Rosa can find anything. She found saffron during a hurricane once.']] }, { t: 'Suggest asking at the port market', reply: [['priya', 'The ships. Of course. Somebody\'s cousin always has a box of something.']] }]]],
    [['priya', 'He didn\'t come Thursday. He always comes Thursday. Every week for two years.'], ['priya', 'He doesn\'t answer his phone. He\'s seventy. He lives alone. I can\'t leave the truck, the lunch rush is starting.'],
      ['choice', [{ t: 'Offer to do a welfare check on him right now', set: 'anjaliCheck', reply: [['narr', 'He\'s home, sitting in his kitchen. He sprained his ankle and was too proud to call. You call Anjali from his porch.']] }, { t: 'Tell her to close the truck and go, and you\'ll meet her there', reply: [['narr', 'She closes the window with forty people in line. He\'s home with a sprained ankle, too proud to call. She cries in his doorway and then yells at him.']] }]]],
    [['narr', 'His birthday. Anjali brings the dal to his apartment. He takes one bite, then another, and puts the spoon down.'], ['narr', 'He doesn\'t say anything for a long time.'], ['priya', 'Papa?']],
    [['priya', 'He said it tasted like his mother\'s kitchen. Then he said, and I quote, "This is better. Don\'t tell your aunt."'], ['priya', 'Then he said he was proud of me. First time. Seventy years old and he finally said it.'],
      ['narr', 'She hands you a little card from the truck. It\'s laminated. It says: LEVEL FIVE. EARNED.'], ['priya', 'You\'re the only one who has one. Don\'t order a five as a dare. Please.']]
  ] },
  hollis: { title: 'Think Before You Move', parts: [
    [['hollis', 'See the kid in the red hoodie? Darnell. Sixteen. Best natural player I\'ve seen in twenty years.'], ['hollis', 'He\'s been hustling games for money. And the boys he walks home with aren\'t chess players.'],
      ['choice', [{ t: 'Ask Hollis what he wants to do about it', reply: [['hollis', 'I want him to think before he moves. Took me nine years to learn that. I\'d like him to learn it cheaper.']] }, { t: 'Offer to talk to Darnell yourself', reply: [['hollis', 'In uniform? He\'ll walk away. Sit down and lose to him first. Then talk.']] }]]],
    [['narr', 'You sit across from Darnell. He beats you in eleven moves and doesn\'t look up.'], ['narr', '"You going to arrest me for playing chess?" he says.'],
      ['choice', [{ t: 'Tell him no, you just wanted a game', set: 'darnellGame', reply: [['narr', 'He resets the board. "Again, then. You\'re bad. You\'re not boring, though."']] }, { t: 'Tell him you\'d rather see him in a tournament than a cell', reply: [['narr', 'He laughs, but he doesn\'t walk away. "A tournament. Okay, officer."']] }]]],
    [['hollis', '(on your work cell) Darnell\'s friends are talking about a car at the transit garage tonight. He\'s with them. He doesn\'t want to be. I can see it on him.'],
      ['choice', [{ t: 'Drive by the garage and be seen, calm and visible', set: 'darnellPresence', reply: [['narr', 'You park under the light with your window down and say good evening. The group drifts apart. Darnell walks to the plaza instead.']] }, { t: 'Call it in as suspicious and wait for backup', reply: [['narr', 'You call it in. By the time units arrive the group has scattered. Nothing happened. Darnell isn\'t at the plaza the next day.']] }]]],
    [['narr', 'Darnell sits across from Hollis. A real game, slow. Forty minutes. Nobody else at the plaza is talking.'], ['narr', 'It ends in a draw. Hollis offers his hand. Darnell takes it.'], ['hollis', 'You thought before every move. Every one. You know what that cost me to learn?']],
    [['hollis', 'He signed up for the state scholastic tournament. In Orlando. He says if he wins he\'s buying me a new board. This one\'s held together with tape.'],
      ['hollis', 'He told me you sat down and lost to him without being weird about it. Said that\'s when he figured you were okay.', { if: 'darnellGame' }],
      ['narr', 'Hollis hands you a small travel chess set, the magnetic kind, worn smooth. Inside the lid, in marker: THINK BEFORE YOU MOVE.'], ['hollis', 'I carried that one inside for nine years. Somebody should carry it outside.']]
  ] },
  // ---------------- Eastside ----------------
  mo: { title: 'Baba, We\'re Open', parts: [
    [['mo', 'You see the sign across the street? A chain station. Twenty-four pumps. Gas eight cents cheaper.'], ['mo', 'My father pumped gas for another man for twenty years so I could have this. Eight cents is going to take it.'],
      ['choice', [{ t: 'Ask what his customers come here for', reply: [['mo', 'Coffee. Talk. The egg salad nobody wants. Me knowing their kids\' names. You can\'t put that on a sign.']] }, { t: 'Ask him what his father would do', reply: [['mo', 'He\'d open at five and say good morning to every person like they were family. That\'s it. That was his whole plan.']] }]]],
    [['mo', 'I need to do something they can\'t do. But I\'m just a gas station.'],
      ['choice', [{ t: 'Suggest free coffee at five for the night-shift workers', set: 'samiCoffee', reply: [['mo', 'The nurses, the bus drivers, the guys from the yards. Coffee at five. Baba would like that.']] }, { t: 'Suggest he put the department\'s thank-you letters up front', set: 'samiLetters', reply: [['mo', 'Up front? People will call me a snitch. ...People already call me a snitch. Okay.']] }]]],
    [['narr', 'A teenager at the counter points at the letters on the wall. "Cop station," he says, and laughs.', { if: 'samiLetters' }], ['narr', 'A teenager at the counter laughs at the free coffee sign. "You trying to get cops in here every morning?"', { unless: 'samiLetters' }],
      ['choice', [{ t: 'Tell the kid what the letters are actually for', reply: [['narr', 'One of them is from the night Sami stayed open in the hurricane so people could charge their phones. The kid reads it. He stops laughing.']] }, { t: 'Let Sami answer for himself', reply: [['mo', 'This is everybody\'s station. Cops, nurses, you. Your mother buys milk here every Tuesday. Tell her I said hi.']] }]]],
    [['narr', 'The chain opens on a Monday with balloons and a man in a gas-pump costume.'], ['narr', 'At five in the morning there\'s still a line at Sami\'s. Two bus drivers, a nurse in scrubs, and the teenager from last week, holding a coffee.']],
    [['mo', 'I had a new sign made. Come look.'], ['narr', 'Over the door, in plain blue letters: YUSUF & SON FUEL · SINCE BABA.'], ['mo', 'Every morning I say "Baba, we\'re open." Now everybody can read it.'],
      ['narr', 'He hands you an egg salad sandwich in wax paper. Taped to it: "First one under the new sign. — Sami."']]
  ] },
  bea: { title: 'The December Batch', parts: [
    [['bea', 'My knees. The doctor says no more all-night standing. And December is coming.'], ['bea', 'My mother\'s batch. By hand, all night, and I give every bit away. I\'ve never skipped a year.'],
      ['choice', [{ t: 'Offer to find her some help for the night', set: 'beaHelp', reply: [['bea', 'Help? Nobody wants to roll dough at two in the morning. ...You\'d be surprised, huh? Okay. Find me some.']] }, { t: 'Ask if she could make a smaller batch this year', reply: [['bea', 'Smaller? My mother would have made two batches. Don\'t you dare say smaller to me again.']] }]]],
    [['bea', 'The man in the nice suit came back. The one from the shelter, 2006. He left a card this time. Daniel Ruiz, accountant.'],
      ['choice', [{ t: 'Suggest she ask Daniel to help with the batch', set: 'beaDaniel', reply: [['bea', 'An accountant rolling dough. He\'ll measure everything twice. Fine. My mother measured nothing.']] }, { t: 'Suggest she ask the shelter if anyone wants to learn', set: 'beaShelter', reply: [['bea', 'Somebody who could use a skill and a warm kitchen at night. Yes. That\'s better than a donation.']] }]]],
    [['narr', 'December, two in the morning. The Donut Stop is full of flour and people who have never made anything by hand.'], ['narr', 'Daniel measures everything twice. Bea yells at him in Spanish. He\'s grinning the whole time.', { if: 'beaDaniel' }], ['narr', 'A young woman from the shelter named Marisa has the best hands in the room. Bea notices in about ten minutes.', { if: 'beaShelter' }],
      ['bea', 'Not like that. Like this. Feel it. The dough tells you when.']],
    [['narr', 'Nine in the morning. The batch goes to the shelter like every year, in boxes stacked to the ceiling of Bea\'s car.'], ['bea', 'All night, and I didn\'t have to go sit in the car once. My knees say thank you. Me too.']],
    [['bea', 'I\'m teaching it. The whole recipe, my mother\'s way. Next year I sit on a stool and supervise.'], ['bea', 'Marisa is going to do the December batch with me every year. She says she\'ll do it when I\'m gone, too.', { if: 'beaShelter' }], ['bea', 'Daniel is coming back next year. He made a spreadsheet of my mother\'s recipe. I let him keep it.', { if: 'beaDaniel' }],
      ['narr', 'She hands you a warm donut with too many sprinkles. "For your kids," she says, and winks.'], ['bea', 'Now there\'s two of us who know it. My mother would have made two.']]
  ] },
  lewis: { title: 'A Friend from the Route', parts: [
    [['lewis', 'You see the yellow house on Birch Lane? Three days of newspapers on the porch. Curtains haven\'t moved.'], ['lewis', 'I know the order. Mail, then curtains. I don\'t like this one.'],
      ['choice', [{ t: 'Do a welfare check right now', set: 'lewisCheck', reply: [['narr', 'Mr. Ferris, 86, is on his kitchen floor. Dehydrated and scared, but alive. You call rescue and stay with him.']] }, { t: 'Ask Lewis to call the family first', reply: [['narr', 'Nobody answers. You check anyway. Mr. Ferris is on his kitchen floor, alive. You call rescue and wish you had come straight over.']] }]]],
    [['lewis', 'Ferris is going to be fine. But who was going to notice? Nobody walks a route anymore. Mail comes in a truck.'], ['lewis', 'There are people on every street like Mrs. Gaines. Waiting for something with their name on it.'],
      ['choice', [{ t: 'Suggest pen pals with the kids at Eastside Middle', set: 'lewisPenpals', reply: [['lewis', 'Kids writing to old folks. Real letters. With stamps. ...They\'d have to learn what a stamp is.']] }, { t: 'Suggest a weekly knock on the door from volunteers', set: 'lewisKnock', reply: [['lewis', 'A route. A walking route, every week, just to knock. I know exactly how to plan that.']] }]]],
    [['lewis', 'Mrs. Gaines\'s daughter came by again. She wants to help. She says her mother kept every one of my letters in a shoebox.'], ['lewis', 'I still don\'t know what to say to her about it.'],
      ['choice', [{ t: 'Tell him he doesn\'t have to say anything', reply: [['lewis', 'Just let her help. Yeah. That\'s what her mother would have wanted. Something to do with her hands.']] }, { t: 'Tell him to say thank you', reply: [['lewis', 'Thank her? I wrote the letters. ...Yeah. She kept them. That\'s worth a thank you.']] }]]],
    [['narr', 'Birch Lane on a Saturday: Lewis with a clipboard, Mrs. Gaines\'s daughter with a tote bag, and a dozen eighth graders with envelopes.', { if: 'lewisPenpals' }], ['narr', 'Birch Lane on a Saturday: Lewis walking his old route with six volunteers, knocking on every door that never gets one.', { if: 'lewisKnock' }],
      ['lewis', 'Mr. Ferris got four letters this week. He read them to me. Twice.']],
    [['narr', 'There\'s an envelope in your locker at HQ. No stamp. Hand-addressed in careful cursive.'], ['narr', 'Inside: "Dear Cadet. Somebody has to notice. You did. Keep noticing. — A friend from the route."'], ['lewis', 'Eleven years of practice. I\'m pretty good at those.']]
  ] },
  andy: { title: 'One Problem at a Time', parts: [
    [['andy', 'There\'s a young guy who\'s been coming to the center. Cole. Marine, home six months. He sits facing the door.'], ['andy', 'I know that chair. I sat in it for two years.'],
      ['choice', [{ t: 'Ask Andy what helped him', reply: [['andy', 'Somebody handing me a board and not asking me anything. One problem at a time. Then the next one.']] }, { t: 'Ask if Cole has anyone looking out for him', reply: [['andy', 'His mom, in Ocala. Me, I guess. That\'s it so far.']] }]]],
    [['andy', 'I want to start a vets\' night here. Thursdays. Chess, coffee, nobody has to talk.'],
      ['choice', [{ t: 'Offer to put it out through the department\'s vet liaison', set: 'andyVets', reply: [['andy', 'You have one of those? Good. Make it sound boring. Boring is how you get vets to show up.']] }, { t: 'Suggest he invite Cole personally', set: 'andyCole', reply: [['andy', 'Not a flyer. A person. Yeah, that\'s how it worked for me.']] }]]],
    [['narr', 'A call: man in crisis behind the community center, upset, pacing, says he doesn\'t want anybody near him. It\'s Cole.'], ['narr', 'Andy is already standing at the corner of the building, hands empty, waiting.'],
      ['choice', [{ t: 'Slow down, give Cole space, and let Andy talk with you', set: 'andyCalm', reply: [['narr', 'You keep your distance and your voice low. Andy sits down on the curb. After twenty minutes, Cole sits down too. Mobile crisis takes it from there.']] }, { t: 'Close the distance and give him clear commands', reply: [['narr', 'Cole backs away and gets louder. Andy steps in and asks you for room. You give it. It takes an hour, and it shouldn\'t have.']] }]]],
    [['narr', 'Thursday night. Seven men and one woman at the center, coffee, chess, almost no talking.'], ['narr', 'Cole is at the board in the corner. His back is to the door.'], ['andy', 'You see that? His back is to the door. Took me two years.']],
    [['andy', 'This is from the tent. The set the four of us played on. I\'ve got the whole thing, except the white knight. It\'s yours.'], ['narr', 'A plastic knight, chipped, held together with green tape.'],
      ['andy', 'You slowed down when it counted.', { if: 'andyCalm' }], ['andy', 'One problem at a time. That\'s the whole job. Mine, yours, his.']]
  ] },
  sunny: { title: 'The Oranges Outlive Us', parts: [
    [['sunny', 'Look at this leaf. See the blotchy yellow? That\'s greening. It\'s in the north rows.'], ['sunny', 'There\'s no cure. It spreads tree to tree. My grandfather\'s trees.'],
      ['choice', [{ t: 'Ask who could help her fight it', reply: [['sunny', 'The county extension office. The university has people who study nothing but this. I\'ve been too proud to call.']] }, { t: 'Ask if she\'s thinking about the offer again', reply: [['sunny', 'Every night. It\'s in the drawer. I haven\'t taken it out yet this week. That\'s something.']] }]]],
    [['sunny', 'I called the extension office. They can treat the healthy rows and replant with tougher stock. It costs money I don\'t have.'],
      ['choice', [{ t: 'Suggest a pick-your-own weekend to raise it', set: 'sunnyPick', reply: [['sunny', 'Strangers in my grove. Kids climbing my trees. ...My grandfather would have charged them a dollar and let them eat as much as they wanted.']] }, { t: 'Suggest selling juice at the Eastside Plaza on Saturdays', set: 'sunnyJuice', reply: [['sunny', 'Next to DJ Jamal? He\'ll name a song after it. Okay.']] }]]],
    [['narr', 'Saturday, Old Grove Farm. The road is lined with parked cars for half a mile. You end up directing traffic for three hours.', { if: 'sunnyPick' }], ['narr', 'Saturday, Eastside Plaza. Sunny\'s juice stand sells out by noon. Jamal plays a song called "Orange You Glad."', { if: 'sunnyJuice' }],
      ['sunny', 'A little boy asked me if oranges grow in the store. I took him to a tree. He looked at me like I was a wizard.']],
    [['sunny', 'The north rows are treated. Two hundred new trees go in next week.'], ['narr', 'She takes the developer\'s offer out of the drawer, reads it one more time, and tears it in half.'], ['sunny', 'His price was everything. Mine is still the oranges outlive us.']],
    [['narr', 'She hands you a small potted orange seedling, about a foot tall.'], ['sunny', 'From the oldest tree in the grove. My grandfather planted it in 1951.'], ['sunny', 'Plant it somewhere you\'re going to stay. That\'s the only rule.']]
  ] },
  jamal: { title: 'A Better Ending', parts: [
    [['jamal', 'The Eastside block party is next Saturday. Biggest one of the year. Word is some guys from across town are coming who don\'t like some guys from here.'], ['jamal', 'I don\'t want to cancel. That\'s what they want. Everybody loses.'],
      ['choice', [{ t: 'Offer to walk the party on foot and talk to people', set: 'jamalFoot', reply: [['jamal', 'Walk around, eat a plate, say hi to aunties. That\'s the kind of police I want there.']] }, { t: 'Suggest he ask for a few extra units on standby', reply: [['jamal', 'On standby, around the corner. Not lined up in front. People feel that. Okay.']] }]]],
    [['jamal', 'I\'ve got the playlist. Every track that ever calmed a crowd down. Grandma songs. Wedding songs.'], ['jamal', 'You got a request? Something that\'s yours?'],
      ['choice', [{ t: 'Give him a song from your family\'s kitchen', set: 'jamalSong', reply: [['jamal', 'Oh, that\'s a good one. That\'s going in the emergency slot.']] }, { t: 'Tell him you trust his judgment', reply: [['jamal', 'Smart. I\'ve been doing this since I was fifteen.']] }]]],
    [['narr', 'Saturday night. Two groups of young men by the fountain, getting louder. A bottle gets put down a little too hard.'], ['narr', 'Jamal sees it. He fades the track and puts on a slow old song every auntie in the plaza knows.'],
      ['choice', [{ t: 'Walk over, easy, and ask the two loudest how their night is going', set: 'jamalTalk', reply: [['narr', 'They expected something else. One of them laughs. His aunt is singing three feet away, very loudly. It\'s over.']] }, { t: 'Stand back and let the song do its work', reply: [['narr', 'The aunties start singing. Then the grandmas. It\'s very hard to fight while your grandma is singing. It works.']] }]]],
    [['narr', 'Midnight. The block party ends with no fights, no arrests, and a hundred people singing the same song.'], ['jamal', 'This one\'s for my cousin, Terrence. Fifteen years. We finally got a good ending.']],
    [['jamal', 'Made you something.'], ['narr', 'A USB drive on a keychain. On it, in silver marker: BETTER ENDINGS VOL. 1.'], ['jamal', 'Track nine\'s yours. You know which song.', { if: 'jamalSong' }], ['jamal', 'Six years, not one fight. Now it\'s six years and one Saturday with you in it.']]
  ] },
  // ---------------- Riverside ----------------
  ines: { title: 'Peanut Butter and Pumpkin', parts: [
    [['ines', 'Duke is retiring. The old shepherd from K-9, Officer Delacruz\'s partner. Nine years on the street.'], ['ines', 'I\'m making the cake. Peanut butter and pumpkin. Delacruz doesn\'t know yet that he\'s going to cry.'],
      ['choice', [{ t: 'Ask if you can help plan the party', set: 'dukeParty', reply: [['ines', 'A party for a dog. You\'re my kind of cadet. Bring tissues.']] }, { t: 'Ask what happens to a police dog after he retires', reply: [['ines', 'Most go home with their handler. Duke already sleeps on Delacruz\'s couch. He just gets to stop working.']] }]]],
    [['ines', 'Who should be there? Duke has a lot of friends. Most of them he arrested.'],
      ['choice', [{ t: 'Invite the second graders Duke visits at Riverside School', set: 'dukeKids', reply: [['ines', 'Thirty seven-year-olds and a cake. Delacruz is going to lose it.']] }, { t: 'Invite every handler and dog in the unit', set: 'dukeUnit', reply: [['ines', 'Eleven dogs in my waiting room. I\'ll need more treats. And a mop.']] }]]],
    [['narr', 'The clinic\'s back room, streamers and a cake shaped like a bone. Duke wears a paper crown and looks embarrassed about it.'], ['narr', 'Thirty second graders sing to him. Duke lies down and lets every one of them pet his ears.', { if: 'dukeKids' }], ['narr', 'Eleven police dogs sit in a row while their handlers clap. Duke gets the first slice.', { if: 'dukeUnit' }],
      ['narr', 'Officer Delacruz makes it about four words into his speech.']],
    [['ines', '(on your work cell) Duke is here. It\'s time. His heart. Delacruz asked if you could come. He doesn\'t want to sit alone.'],
      ['choice', [{ t: 'Go, and sit on the floor with them', set: 'dukeSat', reply: [['narr', 'Delacruz tells Duke about every call they ever worked. Inés stays. The clinic is closed. Nobody looks at a clock.']] }, { t: 'Cover Delacruz\'s calls so he doesn\'t have to leave', reply: [['narr', 'You take his calls for the rest of the shift. He texts you one word at midnight: "Thanks."']] }]]],
    [['ines', 'Delacruz brought this by. He wanted you to have one.'], ['narr', 'A small metal tag stamped with a paw print: DUKE · K-9 · 9 YEARS · GOOD BOY, EVERY DAY.'],
      ['ines', 'You sat with them. That\'s the hardest thing in my whole job, and you just did it.', { if: 'dukeSat' }], ['ines', 'There\'s still a peanut butter treat in my fridge with your name on it. Don\'t make it sad. Come eat it.']]
  ] },
  pearl: { title: 'The Chimney at Low Tide', parts: [
    [['pearl', 'The lowest tide of the year is next month. The chimney of my house comes all the way out. Bricks and everything.'], ['pearl', 'I\'m ninety-one. I would like to touch it once more. Everybody says it\'s an old piling.'],
      ['choice', [{ t: 'Offer to ask Eli to take her out by canoe', set: 'pearlEli', reply: [['pearl', 'Eli? He\'ll make me wear a life jacket. I\'ll look like a marshmallow. ...Fine.']] }, { t: 'Offer to find proof in the library\'s old records', set: 'pearlRecords', reply: [['pearl', 'The 1949 channel survey. They drew every house they flooded. Mine was the yellow one.']] }]]],
    [['pearl', 'The historical society man came by. He told me, very politely, that I\'m confused. "Ma\'am, there were no houses on that bend."'],
      ['choice', [{ t: 'Tell her you believe her', reply: [['pearl', 'Of course you do. You\'re not an idiot. He is. Politely.']] }, { t: 'Tell her the low tide will settle it', reply: [['pearl', 'Bricks don\'t argue. I like that.']] }]]],
    [['narr', 'Dawn, the lowest tide of the year. Eli paddles. Pearl sits in the front in an orange life jacket, giving directions.', { if: 'pearlEli' }], ['narr', 'Dawn, the lowest tide of the year. You walk Pearl to the end of the Riverwalk with a copy of the 1949 survey.', { unless: 'pearlEli' }],
      ['narr', 'A chimney of old red brick stands out of the mud, right where she said. Carved low on one brick: P.L. 1938.'], ['pearl', 'I did that with my daddy\'s screwdriver. I was eight. I got a whipping for it. Worth it.']],
    [['pearl', 'The Gazette did a story. "Riverside Woman Was Right." That\'s the headline. I\'m framing it.'], ['pearl', 'The city is putting a little plaque on the Riverwalk. The historical society man has to give a speech. I\'m going to sit in the front row and smile at him.']],
    [['pearl', 'This is for you. I don\'t need it anymore, I remember it fine.'], ['narr', 'A small black-and-white photo: a yellow house on a riverbank, a girl on the porch with a screwdriver.'],
      ['pearl', 'You keep showing up for whoever\'s left. That\'s the whole secret. I told you there wasn\'t one. I lied a little.']]
  ] },
  nash: { title: 'That\'s Not Nothing', parts: [
    [['nash', 'Neighborhood kids keep climbing the fence to play on my field. Security wants me to call it in.'], ['nash', 'I was those kids. I don\'t want to call anything in.'],
      ['choice', [{ t: 'Suggest a free Saturday clinic, gates open, for real', set: 'nashClinic', reply: [['nash', 'Open the gates. Teach them right. Then they don\'t have to climb. ...The front office is going to hate this.']] }, { t: 'Offer to talk with the kids about the fence first', reply: [['nash', 'Talk to them. Then I\'ll talk to the front office. One thing at a time.']] }]]],
    [['nash', 'There\'s one kid, Luis. Eleven. Swings like he\'s mad at the ball. Plays in sneakers with holes. No glove. Uses his hat.'],
      ['choice', [{ t: 'Suggest Nash give him his old glove', set: 'nashGlove', reply: [['nash', 'My glove from Double-A. I haven\'t touched it in twenty years. ...Yeah. It should be on a hand.']] }, { t: 'Suggest asking the stadium for donated gear', reply: [['nash', 'The team has a whole closet of stuff. I\'ll just "borrow" it. For the kids.']] }]]],
    [['nash', 'Luis tried out for the travel team. He didn\'t make it. He threw his helmet. Now he says he\'s done with baseball.'],
      ['choice', [{ t: 'Tell Nash to tell Luis what his dad told him', set: 'nashDad', reply: [['nash', '"You were good. That\'s not nothing." ...Yeah. I can say that. I\'ve been practicing on this field for ten years.']] }, { t: 'Suggest Luis help run the clinic for the little kids', reply: [['nash', 'Make him a coach. He has to be good in front of the eight-year-olds. That\'ll fix his attitude.']] }]]],
    [['narr', 'The Saturday clinic game. Luis at the plate. Two strikes. He waits on a slow one, doesn\'t try to kill it, and puts it over the left field fence.'], ['narr', 'Nash, by the dugout, doesn\'t cheer. He just nods, slow, like his father would have.']],
    [['nash', 'Luis made the travel team this spring. Starting catcher.'], ['narr', 'Nash hands you a baseball. The seams are worn soft. Written on it in pen: THAT\'S NOT NOTHING.'], ['nash', 'Last ball I hit in pro ball. A single. Nobody remembers it. I do. Now you do.']]
  ] },
  cora: { title: 'The Forty-Second Star', parts: [
    [['cora', 'The Riverwalk Festival is in two weeks. Twenty thousand people. Every year at least one little one gets lost.'],
      ['choice', [{ t: 'Suggest her cart be the official meeting spot for lost kids', set: 'coraSpot', reply: [['cora', 'With a flag on top so the little ones can see it over the crowd. A blue flag. Kids love blue.']] }, { t: 'Ask what she does when she finds a lost kid', reply: [['cora', 'Free ice cream, crouch down, ask their mom\'s name, not "where\'s your mom." Little ones know names. They don\'t know where.']] }]]],
    [['cora', 'Remember star number one? She teaches second grade now. Ms. Hart. She asked if a police officer could come talk to her class about getting lost.'],
      ['choice', [{ t: 'Go, and teach them to find a mom with kids or a worker in a uniform', set: 'coraClass', reply: [['narr', 'Twenty-six second graders practice saying their parents\' full names. One boy knows his mom\'s phone number in a song.']] }, { t: 'Bring Cora along to tell her own story', set: 'coraStory', reply: [['narr', 'Cora tells them about the Ferris wheel in 1971. Ms. Hart tells them about 1998. The kids are very quiet.']] }]]],
    [['narr', 'Festival night. Dispatch: four-year-old boy, red shirt, missing ten minutes near the water.'],
      ['choice', [{ t: 'Broadcast his description and check the water\'s edge first', set: 'coraWater', reply: [['narr', 'Officers sweep the seawall while the description goes out. He isn\'t near the water. He\'s at a blue flag, eating vanilla.']] }, { t: 'Walk the crowd calling his name', reply: [['narr', 'It takes twenty minutes. He\'s at the cart with the blue flag. Next time, the water first and the radio first. Every minute counts near water.']] }]]],
    [['narr', 'His name is Mateo. He told Cora his mom\'s full name, the way Ms. Hart\'s class practiced.'], ['narr', 'His mother runs the last fifty feet. Cora holds out the boy and a napkin at the same time.'], ['cora', 'Forty-two.']],
    [['narr', 'Cora opens the lid of the cart. Forty-two stars now. Next to the newest one, in small letters: "w/ the cadet."'], ['narr', 'She peels a star sticker off the roll and presses it onto the back of your hand.'],
      ['cora', 'I\'m standing where a lost kid would look. So are you now. That\'s what this job is, isn\'t it.']]
  ] },
  eli: { title: 'Kenny\'s Jacket', parts: [
    [['eli', 'Kenny\'s mom still lives on Bayou Road. Every year on the anniversary I drive past her house. I never stop.'], ['eli', 'Thirty-one years. I was the one who didn\'t wear one first.'],
      ['choice', [{ t: 'Ask what he would want to say to her', reply: [['eli', 'That I\'m sorry. That I tell every kid. That it isn\'t enough. I don\'t know.']] }, { t: 'Tell him he doesn\'t have to carry that by himself', reply: [['eli', 'Thirty-one years says otherwise. ...But thanks.']] }]]],
    [['eli', 'Somebody\'s been taking my canoes at night. Teenagers. No life jackets. In the dark. I found one canoe floating upside down.'],
      ['choice', [{ t: 'Talk to the teens at the boat launch, not just run them off', set: 'eliTalk', reply: [['narr', 'Four sixteen-year-olds. You tell them about a boy named Kenny. Eli stands behind you and doesn\'t say anything. The canoes stay put after that.']] }, { t: 'Suggest he lock the canoes and add a light', reply: [['narr', 'He locks them. A week later the kids swim out instead. Eli spends the night on the dock, waiting with a flashlight. They come back. He talks to them himself.']] }]]],
    [['eli', 'Mrs. Ortiz called me. She saw the Gazette story about the teenagers. She asked me to come by.'],
      ['choice', [{ t: 'Offer to go with him', set: 'eliWent', reply: [['narr', 'She opens the door before he knocks. She holds him for a long time. She tells him Kenny would have been the first one to make fun of him for the life jackets.']] }, { t: 'Tell him this one he has to do himself', reply: [['narr', 'He goes alone. He comes back to the dock two hours later with red eyes and a casserole.']] }]]],
    [['narr', 'The boat launch has something new: a wooden rack of bright orange loaner life jackets, free to anyone.'], ['narr', 'Carved into the top board: KENNY\'S RACK. WEAR IT FOR WHOEVER WOULD HAVE TO TELL YOUR MOM.'], ['eli', 'Mrs. Ortiz picked the color. She said Kenny hated orange. She said that\'s the point.']],
    [['eli', 'Here. Every officer who works this river should have one.'], ['narr', 'A plastic whistle on an orange lanyard. Scratched into the whistle: K.O.'], ['eli', 'Twenty years, never lost a customer. Thirty-one years, never stopped Kenny. Both are true. Keep that whistle on you.']]
  ] },
  toby: { title: 'Terrible Coffee', parts: [
    [['toby', 'The post office is moving me to a new route. Next month. Somebody new gets Willow Street.'], ['toby', 'Who\'s going to knock on Mr. Baptiste\'s door? The new guy won\'t know to.'],
      ['choice', [{ t: 'Suggest he train the new carrier on Willow himself', set: 'tobyTrain', reply: [['toby', 'Every dog\'s name. Every porch. Mr. Lewis did it for me. I\'ll do it for him.']] }, { t: 'Suggest asking Mr. Lewis\'s volunteers to add Baptiste', set: 'tobyLewis', reply: [['toby', 'Mr. Lewis has volunteers now? Of course he does. He has a clipboard, doesn\'t he?']] }]]],
    [['toby', 'I told Mr. Baptiste he should wear one of those medical alert buttons. He threw me out. Then he made me coffee. Then he threw me out again.'],
      ['choice', [{ t: 'Suggest Toby tell him about the two days on the floor', reply: [['toby', 'He doesn\'t like to talk about it. ...Maybe he needs to hear it from somebody who found him.']] }, { t: 'Offer to talk to Mr. Baptiste yourself', set: 'tobyTalk', reply: [['narr', 'Mr. Baptiste listens to you, grumbles, and says he\'ll "think about it." Toby says that\'s the closest he\'s ever come to a yes.']] }]]],
    [['narr', 'Toby\'s last day on Willow Street. He walks the new carrier, Jasmine, up to Mr. Baptiste\'s door.'], ['narr', 'Mr. Baptiste makes three cups of coffee. It is genuinely terrible. All three are finished.'], ['toby', 'He\'s wearing the button. He showed it to me like it was a medal.']],
    [['toby', '(on your work cell) Jasmine called me. Mr. Baptiste pushed the button. He slipped in the shower. Rescue got there in nine minutes.'], ['toby', 'Nine minutes. Not two days. Nine minutes.']],
    [['narr', 'A package at HQ, wrapped in a grocery bag. Inside: a chipped mug that says WORLD\'S WORST COFFEE, and a note.'], ['narr', '"Officer. Toby says you helped. Here is the mug. I will still make the coffee. — R. Baptiste"'], ['toby', 'That\'s the mug he used to give me. That\'s a big deal. Don\'t tell him I told you.']]
  ] },
  // ---------------- Industrial ----------------
  tess: { title: 'A Prayer for Every Car', parts: [
    [['tess', 'The railroad is replacing the old switch tower. Automated. Somebody in an office two states away will throw my switches with a mouse.'], ['tess', 'They\'re tearing down the tower next month. The window frame with my grandmother\'s initials goes in a dumpster.'],
      ['choice', [{ t: 'Offer to ask the railroad to save the window frame', set: 'tessFrame', reply: [['tess', 'They\'ll say no. ...Ask anyway. Nobody ever asks them anything.']] }, { t: 'Ask what she\'ll do after the tower closes', reply: [['tess', 'They offered me the office job. Throwing switches with a mouse. I said I\'d think about it. I\'ve been thinking about it with my fists.']] }]]],
    [['tess', 'Kids have been hopping the freight cars at the north end. Riding them a mile and jumping off. One of them is going to lose a leg.'],
      ['choice', [{ t: 'Bring the kids to the tower and let Tess explain how it really works', set: 'tessKids', reply: [['narr', 'Tess shows them a train taking a full mile to stop. Two of the boys go quiet. One asks if he can come back and learn the switches.']] }, { t: 'Increase patrols near the north end', reply: [['narr', 'You park at the north end for a week. The kids find a new spot. Tess shakes her head. "You can chase them or you can teach them."']] }]]],
    [['narr', 'Tess\'s last shift in the tower. The final train is a long freight, ninety cars.'], ['narr', 'She stands at the window and counts every car out loud, the way her grandmother did. You stand behind her. You count too.'],
      ['tess', 'Ninety. Somebody should. ...Okay. That\'s all of them.']],
    [['tess', 'The railroad said yes. They took the window frame out in one piece. They want it in the new dispatch office.', { if: 'tessFrame' }], ['tess', 'The demolition crew let me take one board off the frame. The one with the E.R. on it. I didn\'t ask. They didn\'t see.', { unless: 'tessFrame' }],
      ['tess', 'And I took the office job. Somebody has to say a prayer for the cars. The mouse doesn\'t know how.']],
    [['narr', 'A note at HQ in block capitals, with a small brass switch key on a ring.'], ['narr', '"THE LAST KEY TO THE NORTH SPUR TOWER. GRANDMA WOULD WANT A COP TO HAVE IT. SHE SAID YOU PEOPLE ARE ALWAYS STANDING NEAR THE TRACKS. — TESS"'],
      ['tess', 'One of the boys from the north end starts as a trainee next month. I\'m going to teach him to count.', { if: 'tessKids' }]]
  ] },
  hector: { title: 'The Flagpole on the Long Way', parts: [
    [['hector', 'Got a new kid in the garage. Marcus. Seventeen. His probation officer sent him. He hasn\'t said ten words.'], ['hector', 'He holds a torch like he\'s afraid of it. That\'s actually the right way to start.'],
      ['choice', [{ t: 'Offer to stop by during his lessons', set: 'hectorVisit', reply: [['hector', 'A cop in the garage. He\'ll think it\'s a setup. ...Come anyway. Wear regular clothes.']] }, { t: 'Ask Hector what Marcus is good at', reply: [['hector', 'Patience. Kid can hold a bead steady for a full minute. You can\'t teach that. Somebody taught him how to wait. Probably the hard way.']] }]]],
    [['hector', 'Marcus missed two days. His probation officer called. If he misses one more, he\'s violated.'],
      ['choice', [{ t: 'Go find out why with Hector, before you assume the worst', set: 'hectorWhy', reply: [['narr', 'His little sister was sick and nobody else could watch her. Hector brings soup. You help Marcus call his probation officer to explain. It counts as an excused absence.']] }, { t: 'Tell Hector the probation rules are the rules', reply: [['narr', 'Hector is quiet a long time. "Rules are the rules. The kid is still the kid." He goes to Marcus\'s house alone.']] }]]],
    [['hector', 'I got a letter. Return address is Tampa. It\'s from my son.'], ['hector', 'He\'s working. Roofing. He has a little boy. He wants to know if I want to meet him.'],
      ['choice', [{ t: 'Tell him yes, and offer to drive him there', set: 'hectorSon', reply: [['hector', 'I\'d probably drive into a ditch on my own. Yeah. Okay. Okay.']] }, { t: 'Ask him what he wants to say to his son', reply: [['hector', 'That I\'m sorry. That I tried with a hundred kids because I couldn\'t try with him. That it wasn\'t fair. To either of us.']] }]]],
    [['narr', 'A diner off the interstate in Tampa. Hector\'s son looks exactly like him, thirty years younger. A little boy hides behind his leg.', { if: 'hectorSon' }], ['narr', 'Hector takes the bus to Tampa alone. He calls you from a diner off the interstate. You can hear a little boy laughing in the background.', { unless: 'hectorSon' }],
      ['narr', 'Nobody knows what to say. So Hector talks about welding. His son says he still remembers how to hold a torch.']],
    [['hector', 'Marcus finished his probation. He passed his welding certification. First try.', { if: 'hectorWhy' }], ['hector', 'Marcus\'s first paid job is building the railing at the new bus stop on Coastline. I\'m going to take the long way past that one too.'],
      ['narr', 'Hector hands you a small steel star, cut and polished by hand. Stamped on the back: TEACH THEM LIKE THEY\'RE YOURS.']]
  ] },
  ivy: { title: 'They Always Come Home', parts: [
    [['ivy', 'Somebody\'s been spraying pesticide on the sod farm next door. Wrong kind, wrong time. I lost two hives this week. Forty thousand bees each.'],
      ['choice', [{ t: 'Offer to talk with the farm manager together', set: 'ivyTalk', reply: [['ivy', 'He\'s not a bad man. He just doesn\'t know. Nobody ever told him bees are out in the morning.']] }, { t: 'Explain she can report it to the state agriculture department', reply: [['ivy', 'I don\'t want to get him fined. I want my bees alive. ...Fine. If he won\'t listen, I\'ll call.']] }]]],
    [['narr', 'The farm manager, Glenn, hadn\'t known. He agrees to spray after sundown, when the bees are home.', { if: 'ivyTalk' }], ['narr', 'Glenn didn\'t listen until the state called him. He sprays after sundown now. He doesn\'t wave at Ivy anymore.', { unless: 'ivyTalk' }],
      ['ivy', 'My son called. First time since Easter. I told him about the bees. He actually asked questions.']],
    [['ivy', 'He wants to bring my granddaughter down for the summer. She\'s nine. I\'ve met her twice.'], ['ivy', 'What if she\'s scared of bees? What if she\'s scared of me?'],
      ['choice', [{ t: 'Suggest a small bee suit, sized for a nine-year-old', set: 'ivySuit', reply: [['ivy', 'A little white suit with a little veil. Oh, she\'ll either love it or hate it. Let\'s find out.']] }, { t: 'Suggest letting her taste the honey first, then meet the bees', reply: [['ivy', 'Start with the sweet part. That\'s smart. That\'s how I got started too.']] }]]],
    [['narr', 'Evening at the hives. Ivy\'s granddaughter, Rosie, stands very still in a white suit three sizes too big, watching the bees come home.', { if: 'ivySuit' }], ['narr', 'Evening at the hives. Rosie licks honey off a spoon and watches the bees come home from a safe distance.', { unless: 'ivySuit' }],
      ['narr', 'Rosie counts them. She gets to forty and gives up. "Grandma, they all come back?"'], ['ivy', 'Every single evening, baby. They always come home.']],
    [['ivy', 'Rosie wants to come back every summer. My son says he\'s coming too. To learn the hives. At forty-one.'], ['narr', 'Ivy hands you a small jar of honey, the label written in a child\'s handwriting: ROSIE + GRANDMA HONEY. ORANGE BLOSSOM WEEK.'],
      ['ivy', 'I started this for him. I kept it for myself. And now it\'s bringing him home. Funny how that works.']]
  ] },
  wanda: { title: 'Officer, Common', parts: [
    [['wanda', 'Somebody\'s been dumping trash out on the pine trail. Tires, an old couch. Right in the middle of the scrub jays\' ground.'], ['wanda', 'Florida scrub jays. They\'re threatened. There are maybe six families out here.'],
      ['choice', [{ t: 'Offer to set up a trail camera with her', set: 'wandaCam', reply: [['wanda', 'A camera. That\'s brilliant. I can also use it to get pictures of the barred owl. Two birds, one camera.']] }, { t: 'Offer to organize a trail cleanup', set: 'wandaClean', reply: [['wanda', 'Hector will come. Hector always comes. He says it\'s for the birds. It\'s not for the birds.']] }]]],
    [['narr', 'The camera catches the same white pickup three nights in a row. A contractor dumping to avoid paying the landfill.', { if: 'wandaCam' }], ['narr', 'Twelve people show up. Hector brings a truck and two thermoses of coffee. They haul out nine tires and the couch.', { if: 'wandaClean' }],
      ['wanda', 'Do you know what Hector did? He held the trash bag for me for three hours. Didn\'t say a word. That man.']],
    [['wanda', 'He asked me to have dinner. Hector. At his place. He said he\'d make his mother\'s pozole.'], ['wanda', 'I haven\'t been on a date since 1994. I don\'t know what to wear. I only own bird clothes.'],
      ['choice', [{ t: 'Tell her to wear the bird clothes. He asked her, not an outfit', set: 'wandaBird', reply: [['wanda', 'Khaki and binoculars to a dinner date. ...He\'d probably like that, wouldn\'t he?']] }, { t: 'Tell her to just bring the bird list', reply: [['wanda', 'The bird list. I could show him the scrub jays. That\'s practically a love letter, for me.']] }]]],
    [['narr', 'Dawn on the pine trail. Wanda and Hector sit on a bench, very still, sharing one pair of binoculars.'], ['narr', 'A scrub jay lands on Hector\'s shoulder. He does not move a muscle. Wanda writes something in her notebook, smiling.']],
    [['wanda', 'Here. I made you an official page.'], ['narr', 'A page torn from her bird notebook. Neat handwriting: "OFFICER (Patrolus cityensis). Common. Startles easily. Nests in cruiser. Always comes back when called. FAVORITE SIGHTING."'],
      ['wanda', 'I sat still long enough. Things came to me. You were one of them.']]
  ] },
  pat: { title: 'Two Old Ladies on the Phone', parts: [
    [['pat', 'Thirty years of Christmas Eves. Velvet and I have a rule. Worst call first, funniest call last.'], ['pat', 'She hasn\'t been on your channel for three nights. I asked one of your guys. He said she\'s out sick. Out sick. Velvet is never out sick.'],
      ['choice', [{ t: 'Offer to find out if she\'s okay', set: 'patAsk', reply: [['pat', 'Don\'t tell her I asked. ...No. Tell her. Tell her Pat asked.']] }, { t: 'Suggest Pat call her herself', reply: [['pat', 'In thirty years I\'ve never called her except Christmas Eve. That\'s the rule. ...Rules are dumb.']] }]]],
    [['narr', 'Velvet is in Mercy General. A heart procedure. She\'s fine. She says the hospital food is "a crime and somebody should call it in."'], ['pat', 'A heart thing. And she didn\'t tell me. Thirty years.'],
      ['choice', [{ t: 'Suggest Pat finally go visit her', set: 'patVisit', reply: [['pat', 'In person? She\'ll see I\'m an old lady with bad knees. ...She\'s an old lady with a bad heart. Fair\'s fair.']] }, { t: 'Suggest Pat call her, just this once', reply: [['pat', 'Just this once. It\'s not even Christmas. That\'s practically a scandal.']] }]]],
    [['narr', 'Mercy General, room 412. Pat stands in the doorway holding grocery store flowers.', { if: 'patVisit' }], ['narr', 'Pat calls from the freight office. You can hear Velvet\'s voice through the phone, laughing.', { unless: 'patVisit' }],
      ['narr', 'Velvet looks up. "Pat. You look exactly like you sound." "Is that good?" "It\'s perfect."', { if: 'patVisit' }]],
    [['pat', 'Velvet is back on the radio. First call of the night, she said "Welcome back, everyone." Only one person on that frequency knew she meant me.']],
    [['narr', 'Christmas Eve. On the freight channel, faint through the static, you hear two old voices. Worst call first. Funniest call last.'], ['pat', '(on the radio) Velvet says your cadet laughs like a car alarm. That\'s our funniest call this year. Merry Christmas, kid.'],
      ['narr', 'Then, for the first time in thirty years, they add a third story. Pat tells Velvet about you.']]
  ] },
  lou: { title: 'Signed in My Own Name', parts: [
    [['lou', 'Truck came in today, a company called Gulf Haul. Brakes were shot, tires were bald. The driver had a paper saying it passed inspection last week.'], ['lou', 'It didn\'t pass anything. Somebody signed that paper without looking.'],
      ['choice', [{ t: 'Ask Lou for copies, and bring it to the state\'s commercial vehicle inspectors', set: 'louReport', reply: [['lou', 'The state? I\'ve complained to the state before. ...They\'ll listen to a cop. Here. I made copies of everything. I always make copies.']] }, { t: 'Tell the driver he can\'t take it back out on the road', reply: [['lou', 'He\'s not the problem. He\'s just the guy who has to drive it. The problem is whoever signed that paper.']] }]]],
    [['lou', 'The driver from Gulf Haul. His name\'s Danny. He came back. He said they\'ll fire him if he talks.'], ['lou', 'He\'s twenty. That\'s how old I was. When my brother...'],
      ['choice', [{ t: 'Tell Danny that whistleblower laws protect him', set: 'louDanny', reply: [['narr', 'You go over the protections with him. Danny reads every word twice. Then he picks up a pen.']] }, { t: 'Tell Lou to tell Danny about his brother', reply: [['narr', 'Lou talks for ten minutes. Danny doesn\'t say anything. At the end, he nods once.']] }]]],
    [['narr', 'The state inspectors do a surprise check of Gulf Haul\'s yard. Twenty-two trucks. Fourteen are pulled off the road.'], ['lou', 'Fourteen. That\'s fourteen guys who aren\'t going to have a blowout on I-4 this month.'],
      ['lou', 'Somebody\'s going to lose their license over those papers. Good.']],
    [['lou', 'Danny got a job here. With me. He\'s good with brakes. Better than I was at his age.'], ['lou', 'He signs his own name on every truck now. I didn\'t even teach him that. He just started doing it.']],
    [['narr', 'A coffee can at HQ with your name on the lid. Inside, a single shiny lug nut and a note.'], ['narr', '"The last bolt in the bad jar. The jar\'s full. I\'m starting a new one. — Lou. P.S. My brother\'s name was Ray. Thought you should know it."'],
      ['lou', 'You put your name on what you did too. I noticed.']]
  ] },
  // ---------------- Justice Row ----------------
  alvarez: { title: 'For What', parts: [
    [['alvarez', 'The young man I sentenced in 1990. Curtis Webb. He wrote to me. He\'s applying for a job as a youth counselor.'], ['alvarez', 'He wants a reference letter. From the judge who sent him away. I don\'t know if I\'m the right person or the worst person.'],
      ['choice', [{ t: 'Tell her she might be the only one who can speak to who he was and who he is', set: 'alvTrue', reply: [['alvarez', 'Before and after. I saw both. That\'s true. Nobody else did.']] }, { t: 'Suggest she meet him first and ask what he wants it to say', set: 'alvMeet', reply: [['alvarez', 'Ask him. Of course. Thirty years on the bench and I still forget to ask.']] }]]],
    [['alvarez', 'I\'ve written this letter nine times. Every version sounds like a sentencing.'],
      ['choice', [{ t: 'Suggest she write it as herself, not as a judge', reply: [['alvarez', 'Just Maria. I haven\'t written anything as just Maria in forty years. ...Let me try.']] }, { t: 'Suggest she only write things she saw with her own eyes', reply: [['alvarez', 'Facts. Personal knowledge. No opinions. You\'d have made a good clerk.']] }]]],
    [['narr', 'Gavel Green, under the big oak. Curtis Webb reads the letter slowly. He reads it again.'], ['narr', 'He folds it, puts it in his jacket pocket, and pats the pocket the same way she pats hers.'],
      ['alvarez', 'He said, "You didn\'t have to say all that." I said, "Yes, I did."']],
    [['alvarez', 'Curtis got the job. The kids at the center call him Mr. Webb. He told me one of them is nineteen.'], ['alvarez', 'He asked if I would come talk to them. About the law. About what it can do and what it can\'t.']],
    [['narr', 'An envelope at HQ, the address in neat old-fashioned cursive. Inside is a copy of the letter, with a note clipped to it.'], ['narr', '"For your robe pocket, when you have one. You helped me answer the question. The answer was: for what came after. — M. Alvarez"'],
      ['alvarez', 'Twenty years is a long time. I can\'t give it back. I could give him a page. Sometimes a page is the only thing a judge has left.']]
  ] },
  nico: { title: 'The Oath and the Stamp', parts: [
    [['nico', 'Bar exam is in eight weeks. I\'m studying between espresso shots. Last night I fell asleep on Evidence and woke up on a stack of napkins.'],
      ['choice', [{ t: 'Offer to quiz her on criminal procedure during your breaks', set: 'nicoQuiz', reply: [['nico', 'A real cop quizzing me on search and seizure. That\'s basically cheating. I love it.']] }, { t: 'Ask how her dad feels about it', reply: [['nico', 'He tells every customer at his church. Every single one. The pastor knows my LSAT score.']] }]]],
    [['nico', 'I asked the clerk of court if my dad could stamp my oath. She laughed. Kind of nicely. But she laughed.'],
      ['choice', [{ t: 'Suggest she ask Judge Alvarez, who knows how these things work', set: 'nicoJudge', reply: [['nico', 'The judge who drinks a cortado every morning and tips in quarters? She\'d know. She knows everything.']] }, { t: 'Suggest her dad notarize something else that day', set: 'nicoAlt', reply: [['nico', 'He could stamp my first signed bar card. Or my first case file. That still counts, doesn\'t it?']] }]]],
    [['narr', 'Results day. Nico refreshes the page on her phone between orders. Her hands shake.'], ['narr', 'She drops a cup. It\'s fine. She passed.'], ['nico', 'I passed. I passed. Somebody get me a mop, I\'m crying in the milk.']],
    [['narr', 'The swearing-in ceremony. Judge Alvarez administers the oath herself. When it is done, she nods to the back of the room.', { if: 'nicoJudge' }], ['narr', 'Nico\'s father steps up with his old notary seal. Under the judge\'s eye, he stamps the commemorative certificate.', { if: 'nicoJudge' }],
      ['narr', 'After the ceremony, Nico\'s father stamps her first signed case file with his old notary seal. His hands are steady. Hers aren\'t.', { unless: 'nicoJudge' }]],
    [['nico', 'First case. Public defender\'s office. I\'m going to be on the other side of the table from you someday. Be ready.'], ['narr', 'She hands you a coffee card. Every space already punched. Written on the back: "On the house. For my best study partner. — Nico, Esq."', { if: 'nicoQuiz' }],
      ['narr', 'She hands you a coffee card, every space already punched. "On the house. Keep your reports clean. — Nico, Esq."', { unless: 'nicoQuiz' }]]
  ] },
  greer: { title: 'For the Record', parts: [
    [['greer', 'I\'m retiring. Twenty-eight years. My last trial is next month.'], ['greer', 'My husband says I should finally read the transcripts I typed. I told him I already know what\'s in them.'],
      ['choice', [{ t: 'Ask what she\'ll miss most', reply: [['greer', 'Being the only person in the room whose job is to listen to everybody. Even the ones nobody else listens to.']] }, { t: 'Ask what she won\'t miss', reply: [['greer', 'The testimony I typed with my eyes closed. I won\'t miss that. I\'ll still remember it.']] }]]],
    [['greer', 'You testify in my last trial. I looked at the docket. A burglary. Your case.'],
      ['choice', [{ t: 'Ask her to help you practice your testimony', set: 'greerPrep', reply: [['greer', 'Slower. Clearer. No "um." And answer only what he asks. Most people answer what they wish he\'d asked.']] }, { t: 'Promise to make her last record an easy one', reply: [['greer', 'Speak clearly and don\'t talk over anybody. That would be a lovely retirement present.']] }]]],
    [['narr', 'Courtroom 3B. You take the stand. You speak slowly. You answer only what is asked. Not a single "um."', { if: 'greerPrep' }], ['narr', 'Courtroom 3B. You take the stand. You say "um" twice. Mrs. Greer does not look up. Her fingers keep going.', { unless: 'greerPrep' }],
      ['narr', 'At the end of the day, the judge says, "Let the record reflect that this is Mrs. Greer\'s last trial." Everyone in the room stands up.']],
    [['greer', 'My husband reads me the comics every night. Last night I read them to him. First time in twenty-eight years.'], ['greer', 'He cried at Peanuts. He says it was the Great Pumpkin. I know it was me.']],
    [['narr', 'An envelope at HQ, and inside, a single page of transcript paper, typed.'], ['narr', '"THE OFFICER: Yes, ma\'am. (Testimony clear. No interruptions. A very good witness.) — Final notation, E. Greer, Official Court Reporter."'],
      ['greer', 'I\'ve never added a note to a record before. I figured my last one could have one.']]
  ] },
  felix: { title: 'Two Forms of ID', parts: [
    [['felix', 'An older man came in to sign a power of attorney. His nephew did all the talking. The man barely looked at the paper.'], ['felix', 'I didn\'t notarize it. I said come back when he can tell me what it is himself. The nephew was not happy.'],
      ['choice', [{ t: 'Tell Felix he did the right thing, and ask for the man\'s name', set: 'felixName', reply: [['felix', 'Mr. Okafor. Lives on Bell Street. I wrote it down. I always write it down.']] }, { t: 'Explain he can report a suspected exploitation of an elder to the state hotline', set: 'felixHot', reply: [['felix', 'The abuse hotline handles that? Not just for kids? ...Okay. I\'m calling it right now.']] }]]],
    [['narr', 'Adult protective services visits Mr. Okafor. The nephew had already drained one bank account. The power of attorney would have given him the house.'], ['felix', 'The house. He would\'ve lost the house. Over one stamp.']],
    [['felix', 'Mr. Okafor came in today. By himself. He wants to sign a new power of attorney. His neighbor, Mrs. Chen. He picked her himself.'],
      ['choice', [{ t: 'Suggest Felix read it to him line by line, just to be sure', set: 'felixRead', reply: [['narr', 'Felix reads every line out loud. Mr. Okafor nods, asks two questions and signs. Felix stamps it. It\'s the cleanest stamp he\'s ever made.']] }, { t: 'Suggest Mrs. Chen come in too, so everyone hears it together', reply: [['narr', 'Mrs. Chen comes in with a casserole. Mr. Okafor explains it himself, slowly. Felix stamps it.']] }]]],
    [['felix', 'The goldfish adoption family came back. The goldfish died. They wanted me to notarize the death certificate. I did it. Kids made it. It had a drawing.']],
    [['narr', 'A small envelope at HQ, embossed with a notary seal. Inside: a card that says only THANK YOU, stamped, signed and witnessed.'], ['narr', '"Second best thing I ever put my seal on. Mr. Okafor kept his house. — F."'],
      ['felix', 'You remember the people who sit in that chair. So do you. That\'s the whole job, isn\'t it.']]
  ] },
  ada: { title: 'The Unclaimed Box', parts: [
    [['ada', 'I found something in the unclaimed box. Letters from a woman named Lucille Moreau, 1952. To a sister in Louisiana. Never mailed.'], ['ada', 'Forty-one letters. Every one says she\'s sorry. They never say for what.'],
      ['choice', [{ t: 'Offer to help find the sister\'s family', set: 'adaFind', reply: [['ada', 'An officer who wants to go digging in the archives with me. Bottom shelves first. You remembered.']] }, { t: 'Ask if she has read all of them', reply: [['ada', 'Twice. And I still don\'t know what she was sorry for. That\'s the hardest kind of record. The one that knows more than it tells you.']] }]]],
    [['ada', 'The sister\'s name was Rose. Married name Thibodeaux. Died in 1988. She had a daughter. The daughter is still alive. Lafayette, Louisiana. She\'s ninety.'],
      ['choice', [{ t: 'Suggest Ada write to her before sending the letters', set: 'adaWrite', reply: [['ada', 'Ask first. Of course. Some boxes shouldn\'t be opened by somebody else.']] }, { t: 'Suggest calling the Lafayette police to do a welfare check and pass a message', reply: [['ada', 'A knock on a ninety-year-old woman\'s door from the police. She\'ll think somebody died. ...Somebody did, technically. Let\'s write.']] }]]],
    [['narr', 'A letter comes back from Lafayette in a shaky hand.'], ['narr', '"Mama always said Aunt Lucille was the one who left. She said she never heard from her again. She waited her whole life. Please send them."'],
      ['ada', 'She wrote forty-one times. She never mailed one. And her sister waited forty years by the mailbox.']],
    [['ada', 'The daughter wrote back again. She read all forty-one. She said in the last letter, Lucille finally says what she was sorry for.'], ['ada', 'She didn\'t tell me what it was. She said that one belongs to the family. I said that\'s exactly right.']],
    [['narr', 'An index card at HQ, typed on an old typewriter, the way Ada indexes everything.'], ['narr', '"MOREAU, Lucille. 1919-1961. Letters (41). Delivered 2026, with the help of a patrol officer who checked the bottom shelf. Claimed."'],
      ['ada', 'First card I ever got to type "claimed" on. I\'m keeping a copy. I made you the original.']]
  ] },
  booker: { title: 'The Only Shift I Can Cover', parts: [
    [['booker', 'Davis\'s granddaughter wrote to the Memorial Society. She\'s coming down from Ohio. She wants to see his name.'], ['booker', 'She wants to meet the man who keeps the wall. That\'s me. I\'m the man who traded shifts with her grandfather.'],
      ['choice', [{ t: 'Tell him she\'s coming to meet who he is now, not that day', set: 'bookerNow', reply: [['booker', 'Fifty-some years I\'ve been both. ...Maybe she can tell the difference better than I can.']] }, { t: 'Ask if he wants you there when she comes', set: 'bookerWith', reply: [['booker', 'In uniform. Davis would\'ve liked that. He always said cops and soldiers should get along better.']] }]]],
    [['booker', 'Somebody spray painted the side of the memorial last night. Nothing on the names. Just the back wall.'],
      ['choice', [{ t: 'Pull the nearby business cameras and find out who did it', set: 'bookerCam', reply: [['narr', 'Two teenagers, on a dare. They come back with their parents. Booker hands them each a scrub brush. They work beside him all Saturday.']] }, { t: 'Help him scrub it before the visit', reply: [['narr', 'You and Booker scrub until two in the morning. It comes off. He makes you a cup of instant coffee from a thermos.']] }]]],
    [['narr', 'Veterans Memorial Park. Ellen Davis, forty, carrying a folded flag. She finds her grandfather\'s name with her finger before anyone shows her.'], ['narr', 'Booker tells her about the toothache. His voice breaks at the word "traded."'],
      ['narr', 'Ellen listens all the way through. Then she says, "He would\'ve done the same for you. He\'d have been mad you\'re still carrying it."']],
    [['booker', 'She asked if she could polish his name. I gave her my cloth. She took her time with it. Same as me.'], ['booker', 'Two teenagers showed up today with their own scrub brushes. Nobody asked them to.', { if: 'bookerCam' }]],
    [['narr', 'A package at HQ. Inside, an old polishing cloth, washed and folded, and a note in block capitals.'], ['narr', '"TO THE NEXT ONE WHO STOPS AND READS A NAME. I GOT TO SET DOWN A LITTLE OF IT. THAT\'S YOUR DOING. — SGT. R. BOOKER, U.S. ARMY (RET.)"'],
      ['booker', 'I notice who stops. You stopped for me.']]
  ] }
};

// Choices come back: once a story (or a choice in it) is behind you, the regular's everyday lines remember it, and some
// of them talk about each other. 'arc:id' = that friend's story is finished; 'flag:x' = a choice you made in it.
export const MEMORY3 = {
  walt: [['arc:walt', 'Mrs. Abernathy rode Route 9 to dialysis this morning. On time. She says hi. She says you owe her a visit.'], ['flag:route9Count', 'I still have the clicker. Some mornings I click it for every rider anyway. Habit. Good habit.']],
  tasha: [['arc:tasha', 'Kayla has nights now. She sat with three people this month. She texts me after. Every time, just one word: "Stayed."'], ['flag:tashaOkonkwo', 'Lt. Okonkwo brought flowers to the hospice room again. He apologized to the flowers for being late.']],
  leon: [['arc:leon', 'Danny the firefighter came by the school to read to the second graders. He brought his helmet. They drew him. The arms are very long.']],
  carmen: [['arc:carmen', 'Look up. Over the stove. Yellow, with a little blue flower. I touch it every morning before I light the burner.'], ['flag:carmenSundays', 'Mateo burned the rice on Sunday. Everybody ate it. That\'s how you know it\'s a family.']],
  priya: [['arc:priya', 'Papa came Thursday. He ordered a five to show off. He cried. He says it was the chilies. It was not the chilies.']],
  hollis: [['arc:hollis', 'Darnell beat me in thirty-one moves yesterday. He shook my hand and said "think before you move." To me. The nerve.']],
  mo: [['arc:mo', 'Every morning, five o\'clock: "Baba, we\'re open." The nurses say it with me now. Some of them don\'t even know why.']],
  bea: [['arc:bea', 'Marisa\'s glaze is better than mine now. Don\'t tell her. Don\'t tell anyone. I\'ll deny it.'], ['flag:beaDaniel', 'Daniel came in with a spreadsheet of next December. Color-coded. I let him. My mother is laughing somewhere.']],
  lewis: [['arc:lewis', 'Forty-two names on the route now. Every one gets a knock or a letter every week. Mr. Ferris is the pickiest reader.']],
  andy: [['arc:andy', 'Cole brought a new guy on Thursday. Didn\'t say anything. Just pulled out a chair for him. Facing the door, because the kid needed that. Cole knew.']],
  sunny: [['arc:sunny', 'The north rows have new leaves. Green, all the way through. Did you plant yours yet? Somewhere you\'re going to stay, remember.']],
  jamal: [['arc:jamal', 'Block party last Saturday, no fights. The aunties request "your" song now. I tell them it belongs to a cop. They think I\'m joking.']],
  ines: [['arc:ines', 'Echo, Delacruz\'s new dog, came in for shots. She sat right under Duke\'s photo and wouldn\'t move. Dogs know.']],
  pearl: [['arc:pearl', 'The historical society man brought me a copy of the 1949 survey. He wrote "Pearl was right" in the margin. In pen.'], ['flag:pearlEli', 'Eli comes by every low tide to take me out to the chimney. He still makes me wear that life jacket. I look like a marshmallow, and I don\'t mind.']],
  nash: [['arc:nash', 'Luis threw out a runner at second last night. From his knees. I didn\'t say anything. I just nodded. He knew.']],
  cora: [['arc:cora', 'Forty-two stars. Ms. Hart\'s class sent me a card with a blue flag on it. Twenty-six signatures. One is just a drawing of ice cream.']],
  eli: [['arc:eli', 'Mrs. Ortiz counted a hundred life jackets off the rack this summer. A hundred. Kenny would have hated the attention. I hope he\'s watching anyway.'], ['flag:pearlEli', 'Took Miss Pearl out to her chimney again. She gave me directions the whole way. I\'ve been paddling this river for thirty years.']],
  toby: [['arc:toby', 'Jasmine still drinks Mr. Baptiste\'s coffee every morning. She says it\'s not that bad. She\'s lying. That\'s how I know she cares.']],
  tess: [['arc:tess', 'Ninety-four cars last night. I counted them all. The new kid counted too. Out loud. Grandma would be proud of both of us.']],
  hector: [['arc:hector', 'My grandson called me "Grandpa Sparks." I\'m keeping it. Don\'t tell anybody at the garage.'], ['arc:wanda', 'Wanda put me on her bird list. "Rare. Very patient." I\'ve been called worse. Never been called better.']],
  ivy: [['arc:ivy', 'Rosie called me last night to tell me the bees in Ohio are lazy. She\'s nine. She\'s already a snob about bees. I\'m so proud.']],
  wanda: [['arc:wanda', 'Harold and Mrs. Harold had three chicks this spring. I put them on the list. I put you on there too, you know. Favorite sighting.'], ['arc:hector', 'Hector\'s grandson came up. He made the boy sit still for a scrub jay. The boy lasted four minutes. Hector says that\'s a record.']],
  pat: [['arc:pat', 'Velvet came over for coffee on Sunday. In person. We still did worst calls first. Then she beat me at cards. Legends don\'t lose gracefully.']],
  lou: [['arc:lou', 'Danny caught a bad brake line today that I missed. First time anyone\'s ever caught one I missed. I signed it with both our names.']],
  alvarez: [['arc:alvarez', 'Mr. Webb sent me a picture. His whole group from the center, at their graduation. He wrote on the back: "For what came after."']],
  nico: [['arc:nico', 'I won my first motion today. Suppression hearing. Bad search. I thought of you. In a good way. Keep your searches clean, okay?']],
  greer: [['arc:greer', 'My husband and I finally read a transcript together. One of the funny ones. A man tried to sue his own parrot. We laughed for an hour.']],
  felix: [['arc:felix', 'Mr. Okafor brought me a plant. He said a man who asks questions should have something alive in his shop. It\'s already dying. I\'m trying.']],
  ada: [['arc:ada', 'Two more unclaimed names found their families this month. I type "claimed" slowly now. It\'s my favorite word in the archive.']],
  booker: [['arc:booker', 'Ellen\'s kids polished their great-grandfather\'s name on Memorial Day. The little one did it three times. I didn\'t stop her.']]
};
